type UnauthorizedBehavior = "returnNull" | "throw";

function buildQueryUrl(queryKey: readonly unknown[]): string {
  const [firstSegment] = queryKey;

  if (typeof firstSegment === "string") {
    return firstSegment;
  }

  return queryKey
    .filter((segment): segment is string | number => typeof segment === "string" || typeof segment === "number")
    .map(String)
    .join("/");
}

export const getQueryFn: <T>(options: {
  on401: UnauthorizedBehavior;
}) => QueryFunction<T> =
  ({ on401: unauthorizedBehavior }) =>
  async ({ queryKey }) => {
    const url = buildQueryUrl(queryKey);
    try {
      const res = await fetch(url, {
        credentials: "include",
      });

      if (unauthorizedBehavior === "returnNull" && res.status === 401) {
        return null;
      }

      await throwIfResNotOk(res, { method: "GET", url });

      const contentType = res.headers.get("content-type") ?? "";
      if (!contentType.toLowerCase().includes("application/json")) {
        const text = await res.text();
        throw new Error(`Expected JSON response from ${url}, received ${contentType || "unknown content type"}: ${text.slice(0, 200)}`);
      }

      return await res.json();
    } catch (error) {
      await reportHandledError({
        error,
        request: { method: "GET", url },
      });
      throw error;
    }
  };

